#!/usr/bin/env node
/**
 * Safe GitHub CLI Helper — v1.0.0
 *
 * Prevents injection issues when using `gh` commands with untrusted content
 * (PR bodies, issue bodies, comment bodies) by routing the body through a
 * temp file and using `--body-file` rather than interpolating into shell args.
 *
 * ADR-127 Phase 2 hardening:
 *   - GITHUB_SAFE_VERSION exported for smoke assertions.
 *   - Explicit 256KB body cap: rejects oversized bodies before any temp-file
 *     write, matching the GitHub API `body` field limit.
 *   - Strict error handling: all execSync calls inside try/catch; cleanup in
 *     finally; non-zero exit on any error.
 *   - GITHUB_SAFE_DRY_RUN=1 env-var skips the actual `gh` exec for testing.
 *
 * Usage:
 *   ./github-safe.js issue comment 123 "Message with \`backticks\`"
 *   ./github-safe.js pr create --title "Title" --body "Complex body"
 */

import { execSync, execFileSync } from 'child_process';
import { writeFileSync, unlinkSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import { randomBytes } from 'crypto';

// Version constant — asserted by smoke-github-safe-injection.mjs.
export const GITHUB_SAFE_VERSION = '1.0.0';

// Maximum body size allowed (bytes).  The GitHub API enforces 65536 chars for
// issue/PR bodies; the CLI is more lenient but the 256KB limit is a
// conservative safety cap that prevents accidental oversized writes.
const MAX_BODY_BYTES = 256 * 1024;

const args = process.argv.slice(2);

if (args.length < 2) {
  console.log(`
Safe GitHub CLI Helper v${GITHUB_SAFE_VERSION}

Usage:
  ./github-safe.js issue comment <number> <body>
  ./github-safe.js pr comment <number> <body>
  ./github-safe.js issue create --title <title> --body <body>
  ./github-safe.js pr create --title <title> --body <body>

This helper prevents injection issues with special characters:
- Backticks in code examples
- Command substitution $(...)
- Semicolons and other shell metacharacters
- Oversized bodies (> 256 KB rejected)
`);
  process.exit(1);
}

const [command, subcommand, ...restArgs] = args;

// Handle commands that need body content
if ((command === 'issue' || command === 'pr') &&
    (subcommand === 'comment' || subcommand === 'create')) {

  let bodyIndex = -1;
  let body = '';

  if (subcommand === 'comment' && restArgs.length >= 2) {
    // Simple format: github-safe.js issue comment 123 "body"
    body = restArgs[1];
    bodyIndex = 1;
  } else {
    // Flag format: --body "content"
    bodyIndex = restArgs.indexOf('--body');
    if (bodyIndex !== -1 && bodyIndex < restArgs.length - 1) {
      body = restArgs[bodyIndex + 1];
    }
  }

  if (body) {
    // Enforce 256KB cap before any file I/O.
    const bodyBytes = Buffer.byteLength(body, 'utf8');
    if (bodyBytes > MAX_BODY_BYTES) {
      console.error(
        `[ERROR] Body exceeds maximum allowed size (${bodyBytes} bytes > ${MAX_BODY_BYTES} bytes). ` +
        'GitHub API body fields are capped at 256KB. Truncate the body before passing it to github-safe.js.'
      );
      process.exit(1);
    }

    // Use temporary file for body content — never interpolate into argv.
    const tmpFile = join(tmpdir(), `gh-body-${randomBytes(8).toString('hex')}.tmp`);

    try {
      writeFileSync(tmpFile, body, 'utf8');

      // Build new command with --body-file
      const newArgs = [...restArgs];
      if (subcommand === 'comment' && bodyIndex === 1) {
        // Replace positional body arg with --body-file
        newArgs[1] = '--body-file';
        newArgs.push(tmpFile);
      } else if (bodyIndex !== -1) {
        // Replace --body flag pair with --body-file
        newArgs[bodyIndex] = '--body-file';
        newArgs[bodyIndex + 1] = tmpFile;
      }

      // Skip actual gh exec in dry-run mode (used by smoke tests).
      if (process.env.GITHUB_SAFE_DRY_RUN === '1') {
        const ghArgs = [command, subcommand, ...newArgs];
        console.log(`[DRY-RUN] gh ${ghArgs.join(' ')}`);
        process.exit(0);
      }

      const ghArgv = [command, subcommand, ...newArgs];
      console.log(`Executing: gh ${ghArgv.join(' ')}`);

      // Use execFileSync to avoid shell interpolation — args are passed as an
      // array so shell metacharacters in tmpFile path cannot be exploited.
      execFileSync('gh', ghArgv, {
        stdio: 'inherit',
        timeout: 30000,
      });

    } catch (error) {
      console.error('[ERROR]', error.message);
      process.exit(1);
    } finally {
      // Always clean up the temp file.
      try { unlinkSync(tmpFile); } catch (_) { /* ignore cleanup errors */ }
    }
  } else {
    // No body content — execute normally (no injection risk for args).
    if (process.env.GITHUB_SAFE_DRY_RUN === '1') {
      console.log(`[DRY-RUN] gh ${args.join(' ')}`);
      process.exit(0);
    }
    try {
      execFileSync('gh', args, { stdio: 'inherit' });
    } catch (error) {
      console.error('[ERROR]', error.message);
      process.exit(1);
    }
  }
} else {
  // Non-body commands — 

--- .claude/workflows/full-system-test.js ---
export const meta = {
  name: 'full-system-test',
  description: 'Full system test — CLI build + test suite + runtime smoke + all plugin smoke contracts, run in parallel, with a synthesized pass/fail report',
  phases: [
    { title: 'Test', detail: 'parallel: build, unit tests, CLI runtime smoke, plugin contracts' },
    { title: 'Report', detail: 'synthesize a single green/red verdict' },
  ],
}

// args (optional): { skipTests?: boolean } — skip the (slow) vitest suite, run the rest
const skipTests = !!(args && args.skipTests)

const CLI = 'v3/@claude-flow/cli'

const DIM_SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['dimension', 'ok', 'summary'],
  properties: {
    dimension: { type: 'string' },
    ok: { type: 'boolean' },
    summary: { type: 'string' },
    metrics: { type: 'object', additionalProperties: true },
    failures: { type: 'array', items: { type: 'string' } },
  },
}

const DIMS = [
  {
    key: 'build', agentType: 'coder',
    prompt: `From the repo root, verify the CLI builds cleanly. Run: \`cd ${CLI} && npm run build\` (this runs tsc). Set ok=true ONLY if the build exits 0 with zero type errors. Put the type-error count in metrics.errors and the first few error lines in failures[]. dimension="build". Do NOT modify any files — read/run only.`,
  },
  {
    key: 'unit-tests', agentType: 'tester',
    prompt: `From the repo root, run the CLI automated test suite. In ${CLI}, read package.json "scripts" to find the test command (likely "vitest run" / "npm test"). Run the FULL suite non-interactively (e.g. \`cd ${CLI} && npx vitest run --reporter=dot\` or the package's test script). Put total/passed/failed/skipped in metrics and list notable failing test files in failures[]. ok=true ONLY if failed=0. If the suite is too large to finish in a reasonable time, run as much as you can, set metrics.truncated=true, and report the counts you got. dimension="unit-tests". Do NOT modify tests or source to make anything pass.`,
  },
  {
    key: 'cli-smoke', agentType: 'tester',
    prompt: `From the repo root, smoke-test the built CLI runtime. Ensure ${CLI} is built (if dist/ is missing, run \`npm run build\` there first). Find the entry from ${CLI}/package.json "bin", then run three commands via node and confirm each exits cleanly with sane output: (1) the version flag, (2) --help, (3) \`doctor\`. Record per-command ok in metrics (e.g. metrics.version, metrics.help, metrics.doctor) and put any crash/stack output in failures[]. ok=true if all three run without crashing. dimension="cli-smoke". Do NOT modify files.`,
  },
  {
    key: 'plugin-contracts', agentType: 'tester',
    prompt: `From the repo root, run EVERY plugin smoke contract: for each script matching the glob plugins/*/scripts/smoke.sh, run it with bash and read its trailing "N passed, M failed" line and exit code. Put metrics.totalPlugins, metrics.passing, metrics.failing. List each failing plugin as "<plugin>: M failed" in failures[]. ok=true ONLY if every plugin smoke exits 0. dimension="plugin-contracts". Do NOT modify files — read/run only.`,
  },
]

phase('Test')
const active = DIMS.filter((d) => !(skipTests && d.key === 'unit-tests'))
const results = (await parallel(
  active.map((d) => () =>
    agent(d.prompt, { label: `test:${d.key}`, phase: 'Test', schema: DIM_SCHEMA, agentType: d.agentType })
  )
)).filter(Boolean)

phase('Report')
const failed = results.filter((r) => !r.ok)
const summary = {
  green: failed.length === 0,
  passed: results.length - failed.length,
  total: results.length,
  skippedTests: skipTests,
  dimensions: results.map((r) => ({ dimension: r.dimension, ok: r.ok, summary: r.summary, metrics: r.metrics || {} })),
  failures: failed.flatMap((r) => (r.failures || []).map((f) => `[${r.dimension}] ${f}`)),
}
log(`Full system test: ${summary.passed}/${summary.total} dimensions green${summary.green ? ' — ALL PASS' : ''}`)
return summary


